func contractSignerReturnURL(personalReturnURL string) string {
	parsed, err := url.Parse(personalReturnURL)
	if err != nil {
		return ""
	}
	parsed.Path = "/account/contracts/signers"
	parsed.RawQuery = "verification_return=1"
	return parsed.String()
}

func nilControllerDependency(value any) bool {
	if value == nil {
		return true
	}
	reflected := reflect.ValueOf(value)
	switch reflected.Kind() {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Pointer, reflect.Slice:
		return reflected.IsNil()
	default:
		return false
	}
}

func validTrustedReturnURL(value string) bool {
	parsed, err := url.Parse(value)
	if err != nil || parsed.Host == "" || parsed.Hostname() == "" || parsed.User != nil ||
		parsed.Path != "/account/identity" || parsed.RawQuery != "verification_return=1" || parsed.Fragment != "" {
		return false
	}
	if parsed.Scheme == "https" {
		return true
	}
	hostname := parsed.Hostname()
	loopback := strings.EqualFold(hostname, "localhost")
	if ip := net.ParseIP(hostname); ip != nil {
		loopback = ip.IsLoopback()
	}
	return parsed.Scheme == "http" && loopback
}
